float sdStar5(in vec2 p, in float r, in float rf)
{
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-k1.x,k1.y);
    p.x = abs(p.x);
    p -= 2.0*max(dot(k1,p),0.0)*k1;
    p -= 2.0*max(dot(k2,p),0.0)*k2;
    p.x = abs(p.x);
    p.y -= r;
    vec2 ba = rf*vec2(-k1.y,k1.x) - vec2(0,1);
    float h = clamp( dot(p,ba)/dot(ba,ba), 0.0, r );
    return length(p-ba*h) * sign(p.y*ba.x-p.x*ba.y);
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

vec2 rotate(vec2 point, float angle) {
    float s = sin(angle);
    float c = cos(angle);
    mat2 rotationMatrix = mat2(c, -s, s, c);
    return rotationMatrix * point;
}

vec3 red = vec3(0.9059, 0.0784, 0.2118);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv-=0.5;
    uv*=2.0;
    vec2 uv0= uv;
    uv0.y*=iResolution.y/iResolution.x;



    float grid = 4.*abs(sin(iTime*0.5));
    uv.y+=sin(iTime)*0.1;
    vec2 gridPos = uv*vec2(grid);

    uv = fract(gridPos);
    uv-=0.5;
    uv*=2.0;
    uv.y*=iResolution.y/iResolution.x;

    uv = rotate(uv, pow(sin(3.14*0.5*iTime+floor(length(gridPos.x))), 4.));

    vec3 col = vec3(0.0);

    // stars
    vec2 starOffset = vec2(0.55, 0.4);
    vec2 star = vec2(0.125, 0.40); // star size and thickness
    float rotationAngle = iTime; // Change the angle as needed
    vec2 rotatedUV = rotate(vec2(uv.x-starOffset.x, uv.y-starOffset.y), rotationAngle);
    col += red*(1.0-step(0., sdStar5(rotatedUV, star.x, star.y)));
    rotatedUV = rotate(vec2(uv.x, uv.y-starOffset.y), -rotationAngle);
    col += red*(1.0-step(0., sdStar5(rotatedUV, star.x, star.y)));
    rotatedUV = rotate(vec2(uv.x+starOffset.x, uv.y-starOffset.y), rotationAngle);
    col += red*(1.0-step(0., sdStar5(rotatedUV, star.x, star.y)));

    // bars  
    vec2 bar = vec2(0.17, 0.1); // x for gap y for height
    col += red*(1.0-step(0., sdBox(vec2(uv.x, uv.y+0.05-bar.x), vec2(1.0, bar.y))));
    col += red*(1.0-step(0., sdBox(vec2(uv.x, uv.y+0.05+bar.x), vec2(1.0, bar.y))));

    // main star
    rotatedUV = rotate(uv0, 1.3*cos(iTime+-3.14159));
    col += red*(1.0-step(0., sdStar5(rotatedUV, 4.*star.x, star.y)));

    // invert black to white
    if (col == vec3(0.0)) {
        col = vec3(1.0);
    }
    // Output to screen
    fragColor = vec4(col,1.0);
}
